INSERT INTO public.questions (id, question_code, subject_id, chapter_id, question_type, content, explanation, difficulty, marks, negative_marks, correct_option, raw_text) VALUES ('8e5ec1e9-4aa8-4a73-b32e-f89bdfdc1d2a', 'BIO-LIV-0124', 'a0eebc99-9c0b-4ef8-bb6d-6bb9bd380a13', 'b0eebc99-9c0b-4ef8-bb6d-6bb9bd380b15', 'MCQ', '[{"type": "text", "html": "<p>The word systematics is derived from Greek word systema. Statement II : Systema means systematic arrangement of organisms.</p>"}]'::jsonb, '[{"type": "text", "html": "<p>Refer to NCERT Class 11 Biology: Chapter 1 - The Living World.</p>"}]'::jsonb, 'Medium', 4, 1, 'a', 'The word systematics is derived from Greek word systema. Statement II : Systema means systematic arrangement of organisms.') ON CONFLICT (question_code) DO UPDATE SET raw_text = EXCLUDED.raw_text, content = EXCLUDED.content;
INSERT INTO public.questions (id, question_code, subject_id, chapter_id, question_type, content, explanation, difficulty, marks, negative_marks, correct_option, raw_text) VALUES ('ca2393bf-e590-4a57-8d9d-8418a27f1afc', 'BIO-LIV-0125', 'a0eebc99-9c0b-4ef8-bb6d-6bb9bd380a13', 'b0eebc99-9c0b-4ef8-bb6d-6bb9bd380b15', 'MCQ', '[{"type": "text", "html": "<p>Statement 1 : The first word denoting the genus starts with a small letter in binomial nomenclature. Statement II : The specific epithet starts with a capital letter in binomial nomenclature. Statement1: Each genus may have one or more than one specific epithets representing different organisms having morphological similarities. Statement II : Lion, leopard and tiger are all species of the genus Panthera. Statement 1 : Felidae consists of genus Panthera and Felis. Statement Il : Felidae is a cat family that comprises of lion, tiger, leopard and cat.</p>"}]'::jsonb, '[{"type": "text", "html": "<p>Refer to NCERT Class 11 Biology: Chapter 1 - The Living World.</p>"}]'::jsonb, 'Hard', 4, 1, 'b', 'Statement 1 : The first word denoting the genus starts with a small letter in binomial nomenclature. Statement II : The specific epithet starts with a capital letter in binomial nomenclature. Statement1: Each genus may have one or more than one specific epithets representing different organisms having morphological similarities. Statement II : Lion, leopard and tiger are all species of the genus Panthera. Statement 1 : Felidae consists of genus Panthera and Felis. Statement Il : Felidae is a cat family that comprises of lion, tiger, leopard and cat.') ON CONFLICT (question_code) DO UPDATE SET raw_text = EXCLUDED.raw_text, content = EXCLUDED.content;
INSERT INTO public.questions (id, question_code, subject_id, chapter_id, question_type, content, explanation, difficulty, marks, negative_marks, correct_option, raw_text) VALUES ('4897ce8f-74dc-40b9-8545-2d6345c17bab', 'BIO-LIV-0126', 'a0eebc99-9c0b-4ef8-bb6d-6bb9bd380a13', 'b0eebc99-9c0b-4ef8-bb6d-6bb9bd380b15', 'MCQ', '[{"type": "text", "html": "<p>Class includes related orders. Statement II : Order Primata includes monkey, gorilla and gibbon. Statement Il : Wheat is a dicot plant. Questions Matching Type Match column I with column Il and select the correct option from the codes given below. Column Il Column ! (Order) (Common name) Primata A. Wheat (ii) B. Diptera Mango Sapindales (iii) C. Housefly Poales (iv) Human D.</p>"}]'::jsonb, '[{"type": "text", "html": "<p>Refer to NCERT Class 11 Biology: Chapter 1 - The Living World.</p>"}]'::jsonb, 'Easy', 4, 1, 'c', 'Class includes related orders. Statement II : Order Primata includes monkey, gorilla and gibbon. Statement Il : Wheat is a dicot plant. Questions Matching Type Match column I with column Il and select the correct option from the codes given below. Column Il Column ! (Order) (Common name) Primata A. Wheat (ii) B. Diptera Mango Sapindales (iii) C. Housefly Poales (iv) Human D.') ON CONFLICT (question_code) DO UPDATE SET raw_text = EXCLUDED.raw_text, content = EXCLUDED.content;
INSERT INTO public.questions (id, question_code, subject_id, chapter_id, question_type, content, explanation, difficulty, marks, negative_marks, correct_option, raw_text) VALUES ('45dcc659-2976-45bc-a9d4-6dadf059d37e', 'BIO-LIV-0127', 'a0eebc99-9c0b-4ef8-bb6d-6bb9bd380a13', 'b0eebc99-9c0b-4ef8-bb6d-6bb9bd380b15', 'MCQ', '[{"type": "text", "html": "<p>P : The taxonomic hierarchy for Brassica campestris can be written as Plantae \u2192 Phanerogamae \u2192 Angiospermae \u2192 Dicotyledonae \u2192 Parietales \u2192 Brassicaceae \u2192 Brassica \u2192 campestris Q : Convolvulaceae and Solanaceae are included in the Order Polemoniales. R : Families Felidae and Canidae are included under the Order Carnivora. S : Bryophyta is a category while division is a taxon. Which of the following combinations of above statements is correct?</p>"}, {"type": "image", "src": "https://bsbbyuaqibehvcbwugif.supabase.co/storage/v1/object/public/question-assets/biology/bio_table_13.png", "alt": "Figure/Table Diagram for BIO-LIV-0127"}]'::jsonb, '[{"type": "text", "html": "<p>Refer to NCERT Class 11 Biology: Chapter 1 - The Living World.</p>"}]'::jsonb, 'Medium', 4, 1, 'd', 'P : The taxonomic hierarchy for Brassica campestris can be written as Plantae → Phanerogamae → Angiospermae → Dicotyledonae → Parietales → Brassicaceae → Brassica → campestris Q : Convolvulaceae and Solanaceae are included in the Order Polemoniales. R : Families Felidae and Canidae are included under the Order Carnivora. S : Bryophyta is a category while division is a taxon. Which of the following combinations of above statements is correct?') ON CONFLICT (question_code) DO UPDATE SET raw_text = EXCLUDED.raw_text, content = EXCLUDED.content;
INSERT INTO public.questions (id, question_code, subject_id, chapter_id, question_type, content, explanation, difficulty, marks, negative_marks, correct_option, raw_text) VALUES ('fa92816a-bf25-4b7d-9df4-5c2b7e4a1080', 'BIO-LIV-0128', 'a0eebc99-9c0b-4ef8-bb6d-6bb9bd380a13', 'b0eebc99-9c0b-4ef8-bb6d-6bb9bd380b15', 'MCQ', '[{"type": "text", "html": "<p>Refer to the given table regarding differences between taxon and categories. Taxon Category (i) It deals with objects. It deals with ranking. (ii) Taxon is real. Category is an abstract term. (iii) It belongs to one It may belong to any ranking. particular ranking. Which of the following are correct differences?</p>"}]'::jsonb, '[{"type": "text", "html": "<p>Refer to NCERT Class 11 Biology: Chapter 1 - The Living World.</p>"}]'::jsonb, 'Medium', 4, 1, 'a', 'Refer to the given table regarding differences between taxon and categories. Taxon Category (i) It deals with objects. It deals with ranking. (ii) Taxon is real. Category is an abstract term. (iii) It belongs to one It may belong to any ranking. particular ranking. Which of the following are correct differences?') ON CONFLICT (question_code) DO UPDATE SET raw_text = EXCLUDED.raw_text, content = EXCLUDED.content;
